import React, { useEffect, useState } from 'react';

function App() {
  const [defender, setDefender] = useState('A Measly Worm');
  const [winner, setWinner] = useState('A Measly Worm');
  const [numberOfTimes, setNumberOfTimes] = useState(0);
  const [victoryReason, setVictoryReason] = useState('It is a measly worm');
  const [emoji, setEmoji] = useState('🐛');

  const fetchResults = async () => {
    try {
      const response = await fetch('http://localhost:3000/api/data');

    } catch (err) {
      console.error('Error fetching data:', err);
    }
  };

  // useEffect(() => {
  //   fetchResults();
  // }, []);

  const [input, setInput] = useState('');

  const handleSend = async () => {
    try {
      const response = await fetch('http://localhost:3000/api/send', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: input }),
      });

      if (!response.ok) {
        throw new Error(`Server error: ${response.status}`);
      }

      const data = await response.json();
      setDefender(data.defender || 'Unknown Defender');
      setWinner(data.winner || 'Unknown Winner');
      setNumberOfTimes(data.numberOfTimes || 0);
      setVictoryReason(data.victoryReason || 'No reason provided');
      setEmoji(data.emoji || '❓');
      setInput('');
    } catch (err) {
      console.error('Error sending message:', err);
    }
    //fetchResults();
  };

  return (
    <div>
      <h1>{defender}</h1>
      <h2>Winner: {winner}</h2>
      <h3>Number of Times: {numberOfTimes}</h3>
      <h4>Victory Reason: {victoryReason}</h4>
      <h5>Emoji: {emoji}</h5>
      <input
        type="text"
        value={input}
        onChange={e => setInput(e.target.value)}
        placeholder="Type your challenger's name"
      />
      <button onClick={handleSend}>Battle!</button>
    </div>
  );
}

export default App;
